import os,json,subprocess
from pathlib import Path
base=Path("/srv/projects/iptvpn-bot")
items=[(Path("/etc/iptvpn-bot"),base/"config"),(Path("/root/project-secrets/iptvpn_bot"),base/"private")]
out={"project":"iptvpn-bot","changed":False,"status":"BLOCKED"}
def service_state():
 names=("ssh","nginx","postgresql@16-main","pm2-root","lowcost-europa","pink-iptv-backend","fadego-staging")
 return {n:subprocess.run(["systemctl","is-active",n],capture_output=True,text=True,timeout=5).stdout.strip() for n in names}
moved=[]
try:
 if not base.is_dir() or base.is_symlink():raise RuntimeError("root_missing")
 previous={}
 for src,dst in items:
  if not src.is_dir() or src.is_symlink() or dst.exists() or dst.is_symlink():raise RuntimeError("invalid_source_or_target")
  s=src.stat()
  if s.st_dev!=base.stat().st_dev:raise RuntimeError("cross_filesystem")
  previous[str(src)]=(s.st_dev,s.st_ino,s.st_uid,s.st_gid,s.st_mode&0o777)
 stable=service_state()
 for src,dst in items:
  os.rename(src,dst);moved.append((src,dst))
  os.symlink(str(dst),src)
  t=dst.stat()
  if (t.st_dev,t.st_ino,t.st_uid,t.st_gid,t.st_mode&0o777)!=previous[str(src)] or not src.is_symlink() or src.resolve(strict=True)!=dst:raise RuntimeError("identity_check_failed")
 if service_state()!=stable:raise RuntimeError("service_states_changed")
 out.update(status="MOVED_VERIFIED",changed=True,canonical_config=str(base/"config"),canonical_private=str(base/"private"),original_inode_owner_mode_preserved=True,old_paths_aliases=True,services_unchanged=True)
except Exception as e:
 out["reason"]=str(e)[:160]
 for src,dst in reversed(moved):
  try:
   if src.is_symlink() and src.resolve(strict=False)==dst:src.unlink()
   if dst.is_dir() and not src.exists() and not src.is_symlink():os.rename(dst,src)
  except Exception:out["rollback"]="INCOMPLETE"
print(json.dumps(out,sort_keys=True))
if out["status"]!="MOVED_VERIFIED":raise SystemExit(3)
